import{_ as d,o as e,c as r,a4 as a}from"./chunks/framework.BMj-uaUw.js";const p=JSON.parse('{"title":"用户端需求规格","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、这一端的目标","slug":"一、这一端的目标","link":"#一、这一端的目标","children":[]},{"level":2,"title":"二、谁在用","slug":"二、谁在用","link":"#二、谁在用","children":[]},{"level":2,"title":"三、页面清单","slug":"三、页面清单","link":"#三、页面清单","children":[{"level":3,"title":"拆分依据","slug":"拆分依据","link":"#拆分依据","children":[]}]},{"level":2,"title":"四、数据字段","slug":"四、数据字段","link":"#四、数据字段","children":[{"level":3,"title":"列表项（活动列表用的字段）","slug":"列表项-活动列表用的字段","link":"#列表项-活动列表用的字段","children":[]},{"level":3,"title":"详情（活动详情多返回的字段）","slug":"详情-活动详情多返回的字段","link":"#详情-活动详情多返回的字段","children":[]},{"level":3,"title":"报名记录（我的报名用的字段）","slug":"报名记录-我的报名用的字段","link":"#报名记录-我的报名用的字段","children":[]},{"level":3,"title":"报名状态","slug":"报名状态","link":"#报名状态","children":[]}]},{"level":2,"title":"五、界面要求","slug":"五、界面要求","link":"#五、界面要求","children":[{"level":3,"title":"活动列表","slug":"活动列表","link":"#活动列表","children":[]},{"level":3,"title":"活动详情","slug":"活动详情","link":"#活动详情","children":[]},{"level":3,"title":"报名表单","slug":"报名表单","link":"#报名表单","children":[]},{"level":3,"title":"我的报名","slug":"我的报名","link":"#我的报名","children":[]},{"level":3,"title":"提示与反馈","slug":"提示与反馈","link":"#提示与反馈","children":[]}]},{"level":2,"title":"六、非功能要求","slug":"六、非功能要求","link":"#六、非功能要求","children":[{"level":3,"title":"弱网下的表现","slug":"弱网下的表现","link":"#弱网下的表现","children":[]},{"level":3,"title":"机型与平台适配","slug":"机型与平台适配","link":"#机型与平台适配","children":[]},{"level":3,"title":"性能","slug":"性能","link":"#性能","children":[]}]},{"level":2,"title":"七、验收方式","slug":"七、验收方式","link":"#七、验收方式","children":[]},{"level":2,"title":"八、与管理端的边界","slug":"八、与管理端的边界","link":"#八、与管理端的边界","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"project/mobile.md","filePath":"project/mobile.md","lastUpdated":1789500881000}'),o={name:"project/mobile.md"};function i(n,t,s,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="用户端需求规格" tabindex="-1">用户端需求规格 <a class="header-anchor" href="#用户端需求规格" aria-label="Permalink to &quot;用户端需求规格&quot;">​</a></h1><p>这一页是用户端（uni-app 写的学生端）的<strong>需求规格</strong>。它和管理端的<a href="/frontend-engineering-course/project/requirements.html">需求规格说明</a>是同级的文档，对应的是同一个后端、同一批数据。</p><p><strong>两份规格文档不要混着看。</strong> 管理端那份讲的是组织者和审核员看到的界面；这一份讲学生看到的界面。<strong>同一个活动，两种人看到的东西差别很大。</strong></p><h2 id="一、这一端的目标" tabindex="-1">一、这一端的目标 <a class="header-anchor" href="#一、这一端的目标" aria-label="Permalink to &quot;一、这一端的目标&quot;">​</a></h2><p><strong>让学生用手机完成一件事：看到有什么活动，报名参加，知道审核结果。</strong></p><p>只做这一件事。<strong>不做的事也写清楚</strong>，免得越做越大：</p><table tabindex="0"><thead><tr><th>不做</th><th>为什么</th></tr></thead><tbody><tr><td>签到、核销</td><td>需要现场扫码，超出这一端的范围</td></tr><tr><td>活动评价、打分</td><td>可选功能，会拖长周期</td></tr><tr><td>消息推送、订阅通知</td><td>需要额外的后端能力与平台申请，课时不够</td></tr><tr><td>组织者视角的功能</td><td>那是管理端的事，两端不要互相渗透</td></tr></tbody></table><p><strong>这条边界要守住。</strong> 学生端最容易被加功能 —— “顺手再加个签到吧”“能不能评论” —— 加到最后这一端变得和管理端一样大，而它的核心价值只是“看一眼、报个名”。</p><h2 id="二、谁在用" tabindex="-1">二、谁在用 <a class="header-anchor" href="#二、谁在用" aria-label="Permalink to &quot;二、谁在用&quot;">​</a></h2><p>只有一个角色：<strong>学生</strong>。</p><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>身份</td><td>在校学生，用微信或浏览器打开</td></tr><tr><td>使用场景</td><td>课间、宿舍、走在路上；<strong>单手操作，可能只给三秒钟注意力</strong></td></tr><tr><td>技术水平</td><td>会用微信小程序，但不会为了报名去研究一个界面</td></tr><tr><td>登录意愿</td><td>低。<strong>能先看就不要强制登录</strong></td></tr><tr><td>数据归属</td><td>只看得到自己的报名记录，看不到别人的</td></tr></tbody></table><p><strong>“登录意愿低”这一条决定了整个信息架构。</strong> 活动列表和详情不登录也能看，只有点“报名”才要求登录。反过来做（一进来就登录），大部分学生会直接关掉。</p><p><strong>用户在 <code>user</code> 表里的角色是 <code>STUDENT</code>。</strong> 这是本端要新增的一个角色值 —— 管理端原来只有 <code>ORGANIZER</code> 和 <code>AUDITOR</code>。</p><h2 id="三、页面清单" tabindex="-1">三、页面清单 <a class="header-anchor" href="#三、页面清单" aria-label="Permalink to &quot;三、页面清单&quot;">​</a></h2><p><strong>一共 5 个页面，其中 3 个在底部 tabBar 里。</strong></p><table tabindex="0"><thead><tr><th>页面</th><th>路由</th><th>在 tabBar</th><th>需要登录</th><th>职责</th></tr></thead><tbody><tr><td>活动列表</td><td><code>pages/activity/list</code></td><td>是</td><td>否</td><td>浏览、搜索、筛选活动</td></tr><tr><td>活动详情</td><td><code>pages/activity/detail</code></td><td>否</td><td>否</td><td>看详情、决定要不要报</td></tr><tr><td>报名表单</td><td><code>pages/signup/form</code></td><td>否</td><td>是</td><td>填资料、提交报名</td></tr><tr><td>我的报名</td><td><code>pages/signup/my</code></td><td>是</td><td>是</td><td>看审核状态、取消报名</td></tr><tr><td>我的</td><td><code>pages/user/index</code></td><td>是</td><td>是</td><td>个人信息、退出登录</td></tr></tbody></table><p><strong>启动页是活动列表，不是登录页。</strong> 这是刻意的：先让人看到内容。</p><h3 id="拆分依据" tabindex="-1">拆分依据 <a class="header-anchor" href="#拆分依据" aria-label="Permalink to &quot;拆分依据&quot;">​</a></h3><p><strong>依据一：列表和详情分开。</strong> 详情要展示长文本的活动说明和场次信息，列表页塞不下。<strong>列表只给决策需要的信息</strong>：标题、类型、截止时间、还剩多少名额。</p><p><strong>依据二：报名单独成页。</strong> 报名要填四个字段，放不进详情页。而且报名是个有后果的动作，<strong>单独一页能让用户意识到“我正在提交东西”</strong>，比在详情页底部弹个层更不容易误触。</p><p><strong>依据三：登录不单独成页（在“我的”里）。</strong> 登录是去报名的路上顺手完成的一步，不该让用户提前准备。所以“我的”页里放登录入口，报名按钮发现未登录时也跳过去。</p><h2 id="四、数据字段" tabindex="-1">四、数据字段 <a class="header-anchor" href="#四、数据字段" aria-label="Permalink to &quot;四、数据字段&quot;">​</a></h2><p><strong>活动、报名、用户的字段定义以<a href="/frontend-engineering-course/project/requirements.html">需求规格说明</a>的第四章为准，这一节只讲学生端特有的部分。</strong></p><h3 id="列表项-活动列表用的字段" tabindex="-1">列表项（活动列表用的字段） <a class="header-anchor" href="#列表项-活动列表用的字段" aria-label="Permalink to &quot;列表项（活动列表用的字段）&quot;">​</a></h3><p>比管理端的列表<strong>少</strong>，这是刻意的：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>主键</td></tr><tr><td><code>title</code></td><td>string</td><td>标题，单行超出省略</td></tr><tr><td><code>type</code></td><td>enum</td><td>活动类型，用来显示彩色标签</td></tr><tr><td><code>organizerName</code></td><td>string</td><td>主办方，学生需要知道是谁办的</td></tr><tr><td><code>quota</code></td><td>number</td><td>名额上限</td></tr><tr><td><code>approvedCount</code></td><td>number</td><td>已通过人数</td></tr><tr><td><code>signupDeadline</code></td><td>string</td><td>报名截止时间</td></tr><tr><td><code>status</code></td><td>enum</td><td>活动状态</td></tr><tr><td><code>coverUrl</code></td><td>string | null</td><td>封面图，<strong>可能为空</strong></td></tr></tbody></table><p><strong>列表里没有 <code>description</code>。</strong> 活动说明可能几百字，二十条带下来响应体会大好几倍。说明只在详情接口里返回。</p><p><strong>前端要自己算两个派生值</strong>，不要指望后端加字段：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 剩余名额</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> remaining</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> activity.quota </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> activity.approvedCount)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 是否可报名</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> canSignup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  activity.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SIGNING&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>为什么不让后端返回 <code>remaining</code>？</strong> 因为 <code>remaining</code> 是可以从两个已有字段算出来的，<strong>多一个字段就多一处可能不一致的地方</strong>。这条和管理端的约定一致（看板的 <code>quotaUsageRate</code> 是例外，因为它的算法需要明确约定）。</p><h3 id="详情-活动详情多返回的字段" tabindex="-1">详情（活动详情多返回的字段） <a class="header-anchor" href="#详情-活动详情多返回的字段" aria-label="Permalink to &quot;详情（活动详情多返回的字段）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>offShelf</code></td><td>boolean</td><td>下架标记</td></tr><tr><td><code>description</code></td><td>string</td><td>活动说明，<strong>HTML 字符串</strong></td></tr><tr><td><code>coverUrl</code></td><td>string | null</td><td>封面图</td></tr><tr><td><code>mySignupStatus</code></td><td>enum | null</td><td>我对这个活动的报名状态，<code>null</code> 表示没报过</td></tr><tr><td><code>sessions</code></td><td>array</td><td>已安排的场次</td></tr></tbody></table><p><strong><code>mySignupStatus</code> 是这一端最关键的字段。</strong> 它决定了详情页底部那个按钮显示什么。没有它，详情页要多发一次请求才能知道“我报过没有”。</p><p><strong><code>description</code> 是 HTML，不是纯文本。</strong> 学生端用 <code>&lt;rich-text&gt;</code> 渲染，这个组件只认基础标签（<code>p</code>、<code>div</code>、<code>span</code>、<code>strong</code>、<code>img</code>、<code>a</code>），<strong>复杂样式和 CSS 类名会丢</strong>。所以后端给的说明要克制。</p><h3 id="报名记录-我的报名用的字段" tabindex="-1">报名记录（我的报名用的字段） <a class="header-anchor" href="#报名记录-我的报名用的字段" aria-label="Permalink to &quot;报名记录（我的报名用的字段）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>报名记录 id</td></tr><tr><td><code>activityId</code></td><td>number</td><td>关联活动</td></tr><tr><td><code>activityTitle</code></td><td>string</td><td>活动标题</td></tr><tr><td><code>activityStatus</code></td><td>enum</td><td><strong>关联活动的状态</strong></td></tr><tr><td><code>activityStartTime</code></td><td>string | null</td><td>活动开始时间</td></tr><tr><td><code>venueName</code></td><td>string | null</td><td>场地名称</td></tr><tr><td><code>status</code></td><td>enum</td><td>报名状态</td></tr><tr><td><code>remark</code></td><td>string</td><td>自己填的备注</td></tr><tr><td><code>rejectReason</code></td><td>string | null</td><td>驳回理由，仅 <code>REJECTED</code> 时有值</td></tr><tr><td><code>auditorName</code></td><td>string</td><td>审核人</td></tr><tr><td><code>auditedAt</code></td><td>string | null</td><td>审核时间</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>报名时间</td></tr></tbody></table><p><strong><code>activityStatus</code>、<code>activityStartTime</code>、<code>venueName</code> 这三个是学生端特意要的。</strong> 学生打开“我的报名”时，最想知道的是三件事：<strong>过了没有、什么时候办、在哪儿办。</strong> 这三个字段能一次性回答完，不用再点进详情页。</p><h3 id="报名状态" tabindex="-1">报名状态 <a class="header-anchor" href="#报名状态" aria-label="Permalink to &quot;报名状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>学生能做什么</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>已提交，等审核</td><td>可以取消</td></tr><tr><td><code>APPROVED</code></td><td>审核通过</td><td>可以取消（会释放名额）</td></tr><tr><td><code>REJECTED</code></td><td>被驳回</td><td>看理由，可以重新报（如果还在报名期）</td></tr><tr><td><code>CANCELLED</code></td><td>自己取消的</td><td>可以重新报</td></tr></tbody></table><p><strong>注意 <code>CANCELLED</code> 的记录不会消失。</strong> 它还在列表里，显示成灰色的“已取消”。<strong>删掉的话，学生会以为自己从没报过这个活动，然后再报一次，然后又被拒</strong> —— 保留记录可以避免这一类困惑。</p><h2 id="五、界面要求" tabindex="-1">五、界面要求 <a class="header-anchor" href="#五、界面要求" aria-label="Permalink to &quot;五、界面要求&quot;">​</a></h2><p>移动端的界面要求和桌面端不同，<strong>最核心的差异是“一屏能放多少东西”。</strong></p><h3 id="活动列表" tabindex="-1">活动列表 <a class="header-anchor" href="#活动列表" aria-label="Permalink to &quot;活动列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>呈现方式</th></tr></thead><tbody><tr><td>布局</td><td><strong>卡片列表，不是表格</strong>。一屏大约 3 到 4 张卡片</td></tr><tr><td>标题</td><td>单行，超出省略</td></tr><tr><td>类型</td><td>彩色标签，用字典里的颜色</td></tr><tr><td>报名进度</td><td>“还剩 N 个名额”；<strong>名额为 0 时显示“名额已满”并用红色</strong></td></tr><tr><td>截止时间</td><td>已过期的用灰色显示，并加“已截止”的标记</td></tr><tr><td>封面图</td><td>有就显示（固定高度，<code>aspectFill</code> 裁切），<strong>没有就不留空位</strong></td></tr><tr><td>交互</td><td>点击整张卡片进详情</td></tr></tbody></table><h3 id="活动详情" tabindex="-1">活动详情 <a class="header-anchor" href="#活动详情" aria-label="Permalink to &quot;活动详情&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>呈现方式</th></tr></thead><tbody><tr><td>顶部</td><td>封面图（或默认图），上面叠活动标题与类型标签</td></tr><tr><td>基本信息</td><td>主办方、截止时间、剩余名额，用信息行排列</td></tr><tr><td>场次信息</td><td>有场次就列出时间和场地，<strong>没有场次显示“待安排”</strong></td></tr><tr><td>活动说明</td><td><code>&lt;rich-text&gt;</code> 渲染，限制最大高度并允许展开</td></tr><tr><td>底部固定栏</td><td><strong>始终可见</strong>的报名按钮，含安全区留白</td></tr></tbody></table><p><strong>底部按钮的文案由状态决定</strong>，这是这一端最容易写漏的地方：</p><table tabindex="0"><thead><tr><th>活动状态</th><th>我的报名状态</th><th>按钮文案</th><th>可点</th></tr></thead><tbody><tr><td>任意</td><td><code>PENDING</code> / <code>APPROVED</code> / <code>REJECTED</code></td><td>查看我的报名</td><td>是</td></tr><tr><td><code>SIGNING</code></td><td>无或已取消，名额未满</td><td>立即报名</td><td>是</td></tr><tr><td><code>SIGNING</code></td><td>无或已取消，名额已满</td><td>名额已满</td><td>否</td></tr><tr><td><code>SIGNUP_CLOSED</code></td><td>无或已取消</td><td>报名已截止</td><td>否</td></tr><tr><td><code>FINISHED</code></td><td>无或已取消</td><td>活动已结束</td><td>否</td></tr></tbody></table><p><strong>判断顺序是“先看报没报过，再看活动状态”。</strong> 一个已经报名的学生应该看到“查看我的报名”，而不是“报名已截止”。</p><h3 id="报名表单" tabindex="-1">报名表单 <a class="header-anchor" href="#报名表单" aria-label="Permalink to &quot;报名表单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>呈现方式</th></tr></thead><tbody><tr><td>姓名</td><td>输入框，<strong>从登录信息预填</strong>，可改</td></tr><tr><td>学号</td><td>数字键盘，10 位，<strong>从登录信息预填</strong></td></tr><tr><td>班级</td><td>输入框，选填</td></tr><tr><td>备注</td><td>多行文本，最多 200 字，带字数统计</td></tr><tr><td>提交按钮</td><td>固定在底部，<strong>提交中显示加载态且不可重复点</strong></td></tr></tbody></table><h3 id="我的报名" tabindex="-1">我的报名 <a class="header-anchor" href="#我的报名" aria-label="Permalink to &quot;我的报名&quot;">​</a></h3><table tabindex="0"><thead><tr><th>元素</th><th>呈现方式</th></tr></thead><tbody><tr><td>筛选</td><td>顶部分段器：全部 / 待审核 / 已通过 / 已驳回</td></tr><tr><td>状态</td><td>彩色标签</td></tr><tr><td>驳回理由</td><td><strong>在卡片内单独一块高亮显示</strong>，不能藏进详情页</td></tr><tr><td>时间地点</td><td>已通过的要显示活动时间与场地</td></tr><tr><td>操作</td><td>可取消的状态才显示“取消报名”按钮；点击时要二次确认</td></tr><tr><td>空状态</td><td>“还没有报名记录”，并给一个“去看看活动”的按钮</td></tr></tbody></table><h3 id="提示与反馈" tabindex="-1">提示与反馈 <a class="header-anchor" href="#提示与反馈" aria-label="Permalink to &quot;提示与反馈&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th><th>不用什么</th></tr></thead><tbody><tr><td>提交成功</td><td><strong>弹窗</strong>，说明接下来会发生什么</td><td>一闪而过的提示</td></tr><tr><td>名额已满</td><td>轻提示</td><td>全屏弹窗</td></tr><tr><td>网络错误</td><td>轻提示</td><td>页面内嵌一块错误区域</td></tr><tr><td>取消报名</td><td><strong>二次确认弹窗</strong></td><td>直接执行</td></tr><tr><td>页面加载</td><td>骨架屏</td><td>空白等待</td></tr></tbody></table><p><strong>第一次成功提交后用弹窗而不是轻提示</strong>，因为用户需要知道“组织者会审核，你可以去我的报名看结果” —— 这个信息一句话说不完。</p><h2 id="六、非功能要求" tabindex="-1">六、非功能要求 <a class="header-anchor" href="#六、非功能要求" aria-label="Permalink to &quot;六、非功能要求&quot;">​</a></h2><h3 id="弱网下的表现" tabindex="-1">弱网下的表现 <a class="header-anchor" href="#弱网下的表现" aria-label="Permalink to &quot;弱网下的表现&quot;">​</a></h3><p>学生用手机在校园里，网络不一定好。<strong>三条硬要求：</strong></p><ol><li><strong>每个请求都要有加载态</strong>（骨架屏或转圈），不能点完什么都不发生</li><li><strong>每个请求都要有失败态</strong>，并给“重新加载”的入口</li><li><strong>触底加载失败时，页码要回退</strong>，不能跳过一页数据</li></ol><h3 id="机型与平台适配" tabindex="-1">机型与平台适配 <a class="header-anchor" href="#机型与平台适配" aria-label="Permalink to &quot;机型与平台适配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>小屏</td><td>iPhone SE 这类 320px 宽的屏幕上不出现横向滚动</td></tr><tr><td>大屏</td><td>平板上内容不至于被拉伸变形</td></tr><tr><td>安全区</td><td>底部固定元素不被 iOS 的横条遮挡</td></tr><tr><td>软键盘</td><td>输入框不被键盘挡住</td></tr><tr><td>两端一致</td><td><strong>H5 与微信小程序端都要验证</strong>，不能只看一端</td></tr></tbody></table><h3 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>目标</th></tr></thead><tbody><tr><td>首屏</td><td>活动列表 10 条数据，3 秒内出现</td></tr><tr><td>图片</td><td>活动封面用 <code>aspectFill</code> 并限制高度，<strong>不打原图</strong></td></tr><tr><td>包体积</td><td>小程序端主包不超限（超了要分包）</td></tr></tbody></table><h2 id="七、验收方式" tabindex="-1">七、验收方式 <a class="header-anchor" href="#七、验收方式" aria-label="Permalink to &quot;七、验收方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>验收项</th><th>怎么验</th></tr></thead><tbody><tr><td>1</td><td>未登录能浏览</td><td>清空 storage，打开活动列表和详情，都能正常显示</td></tr><tr><td>2</td><td>未登录点报名</td><td>提示先登录并跳登录页，登录后能回到报名流程</td></tr><tr><td>3</td><td>报名的四道拦截</td><td>分别造“活动已结束”“已过截止”“名额已满”“已报过名”四种情况，提示各不相同</td></tr><tr><td>4</td><td>按钮状态机</td><td>按第五章那张表逐行切换验证，五种文案都正确</td></tr><tr><td>5</td><td>报名后可查</td><td>“我的报名”里出现新记录，状态是待审核</td></tr><tr><td>6</td><td>驳回可见</td><td>用管理端把一条报名驳回，学生端能看到理由</td></tr><tr><td>7</td><td>取消释放名额</td><td>取消已通过的报名，详情页的名额数字增加</td></tr><tr><td>8</td><td>两端一致</td><td>上述七项在 H5 与微信小程序端各跑一遍</td></tr></tbody></table><p><strong>第 3 项是重点。</strong> 正常流程谁都能走通，<strong>答辩时老师问的往往是这四种异常情况。</strong></p><h2 id="八、与管理端的边界" tabindex="-1">八、与管理端的边界 <a class="header-anchor" href="#八、与管理端的边界" aria-label="Permalink to &quot;八、与管理端的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>管理端</th><th>用户端</th></tr></thead><tbody><tr><td>接口前缀</td><td><code>/api/auth</code>、<code>/api/activities</code> 等</td><td><code>/api/student/*</code></td></tr><tr><td>数据范围</td><td>组织者看自己的，审核员看全部</td><td>只看已发布未下架的，只看自己的报名</td></tr><tr><td>登录方式</td><td>账号密码</td><td>账号密码加微信小程序登录</td></tr><tr><td>技术栈</td><td>Vue 3 加 Element Plus</td><td>uni-app 加 Wot UI</td></tr><tr><td>部署</td><td>Nginx 静态站点</td><td>H5 站点加微信小程序</td></tr></tbody></table><p><strong>两端共用同一个后端与同一套接口约定。</strong> <code>code</code> 加 <code>message</code> 加 <code>data</code> 的响应结构、业务码、分页结构、鉴权方式，全部一致 —— 见<a href="/frontend-engineering-course/project/api.html">接口约定</a>。</p><p><strong>这就意味着：用户端不需要重新设计数据流。</strong> 请求层怎么封装、状态怎么分四种、错误码怎么映射，管理端已经趟过一遍，用户端照着做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>用户端只有一个角色（学生），<strong>只做一件事：看活动、报名、看结果</strong></li><li><strong>启动页是活动列表，浏览不要求登录</strong>，只有报名才要求</li><li>5 个页面，3 个在 tabBar；登录不单独占一个页面</li><li><strong>列表不返回活动说明</strong>，详情才返回；<code>mySignupStatus</code> 决定详情页的按钮</li><li>详情页的按钮是<strong>状态机</strong>，判断顺序是先看报没报过</li><li><strong>驳回理由要在列表里就显示</strong>，那是学生最想看的信息</li><li>弱网和异常路径是验收重点：<strong>四种拦截、五种按钮状态，两端都要跑</strong></li></ul><p>下一步：用户端怎么做，看<a href="/frontend-engineering-course/mobile/">用户端 · uni-app 实战</a>。参考实现见<a href="/frontend-engineering-course/project/impl-mobile-auth.html">用户端 · 登录与登录态</a>。</p>`,74)])])}const b=d(o,[["render",i]]);export{p as __pageData,b as default};
